"""Build the N063 public NFL review from pinned, sanitized owner evidence.

All original research values remain unchanged.  This builder performs no model
fitting and never rescores rounded public cards. It was newly implemented after
workspace interruption; it is not claimed to reproduce a lost HTML byte stream.
"""
from __future__ import annotations
import argparse
import base64
import collections
import gzip
import hashlib
import json
import math
import re
from pathlib import Path
from datetime import datetime

HERE = Path(__file__).resolve().parent
PROJECTION_NAME = "public_projection_n063.json.gz"
PROJECTION_PIN = {"bytes":144555,"sha256":"7a3fc11503c20cb3bc485fe0fdc47e8661d7f3f9c71132f6e6a9335a815245ee"}
RETAINED_PIN = {"bytes":611972,"sha256":"c4af5429d9db420f75655c6b72d691334f8675481ca403e661a36b3e45c8cd69"}
FORBIDDEN_KEYS = {"bucket","raw_source","source_sha256","recipe_id","selected_recipe_id",
                  "feature_names","feature_columns","weights","token_id","ticker",
                  "decimal_price","orderbook","bid","ask","access_key","secret_key"}
FORBIDDEN_TEXT = re.compile(r"s3://|sagemaker-user|tracks/nfl/(?:raw|derived)/|560403859723|AKIA[0-9A-Z]{16}",re.I)

def canonical(value):
    return (json.dumps(value,sort_keys=True,separators=(",",":"),allow_nan=False)+"\n").encode()

def identity(body):
    return {"bytes":len(body),"sha256":hashlib.sha256(body).hexdigest()}

def instant(value):
    stamp=datetime.fromisoformat(value.replace("Z","+00:00"))
    if stamp.tzinfo is None:raise ValueError("Timezone-aware public provenance required")
    return stamp

def _walk(value):
    if isinstance(value,dict):
        for key,child in value.items():
            if key in FORBIDDEN_KEYS:raise ValueError("Private field in bounded public projection: "+key)
            _walk(child)
    elif isinstance(value,list):
        for child in value:_walk(child)
    elif isinstance(value,float) and not math.isfinite(value):
        raise ValueError("Nonfinite public metric")
    elif isinstance(value,str) and FORBIDDEN_TEXT.search(value):
        raise ValueError("Private path or credential in public projection")

def validate(data):
    _walk(data)
    if (data["schema"],data["publication_cycle"],data["actual_owner_cycle"])!=("nfl.public.n063.actual-n062.v1","N063","N062"):
        raise ValueError("Public owner/release identity changed")
    owner=data["owner_actual"];prepared=data["n063_execution"]
    if owner["status"]!="PARTIAL_OWNER_CONTINUATION_REPAIR_REQUIRED" or owner["owner_research_acceptance"] is not False:
        raise ValueError("Original partial owner state was promoted")
    if [owner[k]for k in ("new_fits","new_native_fits","new_meta_fits","new_issued_rows")]!=[25030,20886,4144,3650]:
        raise ValueError("Actual N062 counts changed")
    if prepared["status"]!="PREPARED_NOT_OWNER_EXECUTED" or any(prepared[k]!=0 for k in ("new_forecasts","new_provider_observations","new_scientific_fits")):
        raise ValueError("Prepared N063 received invented execution credit")
    if not instant(owner["started_at"])<instant(owner["finished_at"]):raise ValueError("Owner clock ordering changed")
    games=data["games"];ids={g["game_id"]for g in games}
    if len(ids)!=272 or len(games)!=272 or any(g["season"]!=2026 for g in games):
        raise ValueError("Full current-season event census changed")
    completed=[g for g in games if g["completed"]]
    if len(completed)!=135 or sum(g["home_score"]==g["away_score"]for g in completed)!=1:
        raise ValueError("Current final/decisive/tie populations changed")
    for g in games:
        if g["completed"]:
            if any(type(g[k])is not int or g[k]<0 for k in ("home_score","away_score")):raise ValueError("Invalid public final")
            if g["home_margin"]!=g["home_score"]-g["away_score"] or g["total_points"]!=g["home_score"]+g["away_score"]:
                raise ValueError("Final totals differ from original scores")
        elif any(g.get(k)is not None for k in ("home_score","away_score","home_margin","total_points")):
            raise ValueError("Future game was assigned a result")
    history=data["historical_games"]
    if len({g["game_id"]for g in history})!=570 or collections.Counter(g["season"]for g in history)!={2024:285,2025:285}:
        raise ValueError("Two complete public historical-result seasons required")
    cards=data["issued_cards"];by_game={g["game_id"]:g for g in games}
    if len(cards)!=113 or len({c["game_id"]for c in cards})!=113:raise ValueError("Selected original-card cohort changed")
    for card in cards:
        g=by_game[card["game_id"]]
        if g["completed"] or "TBD"in g.get("status_detail","") or set(card["targets"])!={"win","margin","total"}:
            raise ValueError("Original research card/event scope invalid")
        if card["status"]!="ORIGINAL_ISSUED_RESEARCH_CARD" or card["automatic_promotion"]:
            raise ValueError("Original issue classification changed")
        if card["coherent_joint_score_distribution"] or card["conditional_threshold_probability_supported"]:
            raise ValueError("Unadmitted distribution capability")
        for target,row in card["targets"].items():
            value=row["prediction"]
            if type(value)not in (int,float) or not math.isfinite(value):raise ValueError("Unsupported displayed prediction")
            if target=="win" and not 0<=value<=1:raise ValueError("Probability outside unit interval")
            if row["proper_scores_recomputed_from_display"]is not False:raise ValueError("Rounded public display was rescored")
            clocks={k:instant(row[k])for k in ("actual_issue_at_utc","decision_cutoff_at","feature_snapshot_cutoff_at",
                "maximum_training_label_available_at","model_completed_at_utc","model_ready_at_utc",
                "source_origin_at_utc","registered_game_cutoff_at","local_issue_durable_at_utc")}
            if not (clocks["source_origin_at_utc"]<=clocks["feature_snapshot_cutoff_at"]<=clocks["decision_cutoff_at"]
                    <clocks["model_completed_at_utc"]<=clocks["model_ready_at_utc"]<=clocks["actual_issue_at_utc"]
                    <=clocks["local_issue_durable_at_utc"]<clocks["registered_game_cutoff_at"]<instant(g["kickoff_utc"])):
                raise ValueError("Source/fit/issue chronology differs")
            if not clocks["maximum_training_label_available_at"]<clocks["model_completed_at_utc"]:
                raise ValueError("Training label arrives after fit")
    cells=data["provider_cells"]
    expected={(gid,p,t)for gid in ids for p in ("DraftKings","Kalshi","Polymarket")for t in ("win","margin","total")}
    if len(cells)!=2448 or {(r["game_id"],r["provider"],r["target"])for r in cells}!=expected:
        raise ValueError("Complete equal provider/target census required")
    if any(r["qualified_probability"]is not None or not r["reason_codes"]for r in cells):
        raise ValueError("Unproved provider probability or missing reason")
    if len(data["season_metrics"])!=540 or len(data["paired_comparisons"])!=252 or len(data["chosen_policy_metrics"])!=12:
        raise ValueError("Actual historical metric population changed")
    expected_counts={("retained_n061","win"):121,("retained_n061","margin"):122,("retained_n061","total"):122,
                     ("score_history_n062","win"):134,("score_history_n062","margin"):135,("score_history_n062","total"):135}
    chosen=[r for r in data["chosen_policy_metrics"]if r["season"]==2026]
    if {(r["study"],r["target"]):r["n"]for r in chosen}!=expected_counts:
        raise ValueError("Target-specific selected cohort changed")
    if any(r["selected_from_current_season"] or r["metric_recomputed_here"]for r in data["chosen_policy_metrics"]):
        raise ValueError("Historical selected metrics were retuned or recomputed")
    if data["negative_findings"]["score_graph_isolated_comparisons"]!=18 or data["negative_findings"]["holm_significant"]!=0:
        raise ValueError("Negative paired findings changed")
    injury=data["injuries"]
    if (injury["source_rows"],injury["future_pregame_admitted_rows"],injury["post_start_monitoring_only_rows"])!=(362,32,330):
        raise ValueError("Injury temporal admission populations changed")
    if injury["absence_is_known_healthy"] or injury["full_roster_coverage_claimed"]:
        raise ValueError("Injury absence was promoted to complete health")
    return data

def load():
    raw=(HERE/PROJECTION_NAME).read_bytes()
    if identity(raw)!=PROJECTION_PIN:raise ValueError("Committed current public projection physical identity changed")
    current=validate(json.loads(gzip.decompress(raw)))
    old_raw=(HERE/"public_projection_n062.json.gz").read_bytes()
    if identity(old_raw)!=RETAINED_PIN:raise ValueError("Immutable retained projection changed")
    retained=json.loads(gzip.decompress(old_raw))
    rows=retained["scoreboards"]
    if len(rows)!=1349:raise ValueError("Retained archive row census changed")
    _walk(rows)
    return {"current":current,"retained":{"source":"public_projection_n062.json.gz","observed_at":retained["observed_at"],
            "role":"Separate immutable earlier scoreboards; original cohorts and qualifications retained","rows":rows}}

def build(data=None):
    value=load() if data is None else data
    validate(value["current"]);_walk(value["retained"])
    payload=base64.b64encode(gzip.compress(canonical(value),compresslevel=9,mtime=0)).decode()
    return TEMPLATE.replace("__PAYLOAD__",payload).replace("__PROJECTION_SHA__",PROJECTION_PIN["sha256"])

